<?php
declare(strict_types=1); session_start(); require_once __DIR__ . '/../config.php'; if(($_SESSION['admin_role']??'')!=='admin'){header('Location: admin-login.php');exit;} $codes=db()->query("SELECT code,description,minimum_order_amount,expires_at,status,used_count FROM promo_codes ORDER BY id DESC LIMIT 200")->fetchAll(); function promoEscape(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Promo Codes</title><style>body{margin:0;background:#f4f8f6;font-family:Arial;color:#14201d}.bar{padding:18px 5%;background:#10231e;color:#fff;display:flex;justify-content:space-between}.bar a{color:#fff}.page{max-width:1100px;margin:30px auto;padding:0 18px}.table{background:#fff;border-radius:16px;overflow:auto;box-shadow:0 12px 30px #1232}.table table{width:100%;border-collapse:collapse;min-width:700px}.table th,.table td{padding:14px;text-align:left;border-bottom:1px solid #e5eeea}.table th{background:#f4f8f6;color:#52645e}</style></head><body><header class="bar"><strong>Promo Codes</strong><a href="admin-dashboard.php">Dashboard</a></header><main class="page"><h1>Generated promo codes</h1><section class="table"><table><thead><tr><th>Code</th><th>Minimum</th><th>Expires</th><th>Used</th><th>Status</th></tr></thead><tbody><?php if(!$codes): ?><tr><td colspan="5">No promo codes generated yet.</td></tr><?php else: foreach($codes as $code): ?><tr><td><strong><?=promoEscape($code['code'])?></strong></td><td>৳<?=number_format((float)$code['minimum_order_amount'],2)?></td><td><?=promoEscape($code['expires_at']??'—')?></td><td><?= (int)$code['used_count'] ?></td><td><?=promoEscape($code['status'])?></td></tr><?php endforeach; endif; ?></tbody></table></section></main></body></html>
